1	# ---------------------------------------------------------------------------------------------------------------------
2	# REQUIRED PARAMETERS
3	# These variables must be set.
4	# ---------------------------------------------------------------------------------------------------------------------
5	variable "env" {
6	  description = "The environment that the bucket is for, i.e. dev, staging, or prod"
7	  type        = string
8	  validation {
9	    condition = (
10	      var.env != null &&
11	      var.env != ""
12	    )
13	    error_message = "Env must be set"
14	  }
15	}
16	
17	variable "vpc_id" {
18	  description = "The ID of the VPC that the RDS Instance(S) will be deployed into."
19	  type        = string
20	}
21	variable "private_subnet_ids" {
22	  description = "List of private subnets in the VPC that is used to create the RDS Subnet Group"
23	  type        = list(string)
24	}
25	
26	variable "trusted_cidr_blocks" {
27	  description = "CIDR blocks that will be allowed to access the RDS instance on port 5432"
28	  type        = list(string)
29	}
30	
31	variable "pg_version" {
32	  description = "Postgres database version prefix"
33	  type        = string
34	}
35	
36	# ---------------------------------------------------------------------------------------------------------------------
37	# OPTIONAL PARAMETERS
38	# These variables are configurable, but have reasonable defaults set.
39	# ---------------------------------------------------------------------------------------------------------------------
40	
41	variable "name" {
42	  description = "The name of the RDS instance."
43	  type        = string
44	  default     = ""
45	}
46	
47	variable "db_name" {
48	  description = "Database name to create when creating the DB instance"
49	  type        = string
50	  default     = ""
51	}
52	
53	variable "admin_username" {
54	  description = "Database admin user"
55	  type        = string
56	  default     = "immuta_postgres"
57	}
58	
59	variable "rds_instance_size" {
60	  description = "RDS instance size to use."
61	  type        = string
62	  default     = "db.t4g.small"
63	}
64	
65	variable "parameters" {
66	  description = "A map of DB parameters to apply via a parameter group.  If map is empty, the default parameter group will be used"
67	  type        = set(map(string))
68	  default     = []
69	}
70	
71	variable "max_allocated_storage" {
72	  description = "Upper limit on storage expansion from Storage Autoscaling."
73	  type        = number
74	  default     = 50
75	}
76	
77	variable "allocated_storage" {
78	  description = "Upper limit on storage expansion from Storage Autoscaling."
79	  type        = number
80	  default     = 20
81	}
82	
83	variable "kms_key_arn" {
84	  description = "Optional variable for providing a pre-existing KMS key"
85	  type        = string
86	  default     = ""
87	}
88	
89	variable "storage_encrypted" {
90	  description = "Whether or not to encrypt the RDS instance."
91	  type        = bool
92	  default     = true
93	}
94	
95	variable "storage_type" {
96	  description = "Storage type of the RDS instance"
97	  type        = string
98	  default     = "gp3"
99	}
100	
101	variable "encrypt_replicas" {
102	  description = "Whether or not to encrypt the replicas of the RDS instance."
103	  type        = bool
104	  default     = true
105	}
106	
107	variable "enhanced_monitoring_enabled" {
108	  description = "Whether or not to enable enhanced monitoring."
109	  type        = bool
110	  default     = true
111	}
112	
113	variable "performance_insights_enabled" {
114	  description = "Whether or not to enable performance insights."
115	  type        = bool
116	  default     = true
117	}
118	
119	variable "final_snapshot" {
120	  description = "Must be true if you want to destroy backups AND the bucket, if false, bucket must be empty before destruction."
121	  type        = bool
122	  default     = false
123	}
124	
125	variable "multi_az" {
126	  description = "Indicates whether or not the RDS instance should be deployed as a multi-az cluster for HA."
127	  type        = bool
128	  default     = false
129	}
130	
131	variable "subnet_group_name_override" {
132	  description = "Optional override for subnet group name. Can be used when moving DB Subnet Groups."
133	  type        = string
134	  default     = ""
135	}
136	
137	variable "dba_security_group_name_override" {
138	  description = "Optional override for external access SG name. Can be used when moving DB Subnet Groups."
139	  type        = string
140	  default     = ""
141	}
142	
143	variable "security_group_name_override" {
144	  description = "Optional override for local access sg name. Can be used when moving DB Subnet Groups."
145	  type        = string
146	  default     = ""
147	}
148	
149	variable "ca_cert_identifier" {
150	  description = "RDS CA cert identifier"
151	  type        = string
152	  default     = "rds-ca-rsa2048-g1"
153	}
154	
155	variable "backup_retention_period" {
156	  description = "The days to retain backups for. Must be between 0 and 35."
157	  type        = number
158	  default     = 21
159	}
160	
161	variable "replica_retention_period" {
162	  description = "The retention period for backup replication in days. Must be between 0 and 35."
163	  type        = number
164	  default     = 21
165	}
166	
167	variable "kms_key_deletion_window_in_days" {
168	  description = "The default value to use for deletion_window_in_days (the number of days to keep the KMS master key & replica keys after deletion pending)"
169	  type        = number
170	  default     = 30
171	}
172	
173	variable "tags" {
174	  description = "A map of tags to apply to the created resources."
175	  type        = map(string)
176	  default     = {}
177	}
178

